const LESSONS = [L1, L2, L3, L4, L5, L6, L7, L8, L9, L10]
// ─── Дополнения по аудиту полноты: серии кадров, текстовые эквиваленты, разборы ──────────
type Par = ReturnType<typeof p>
const LK = (k: string): AccLesson => (LESSONS as AccLesson[]).find(l => l.key === k) as AccLesson
const ins = (k: string, after: string, ...ps: Par[]) => {
  const arr = LK(k).content.paragraphs
  const i = arr.findIndex(x => x.id === after)
  if (i < 0) throw new Error(`ins: нет абзаца ${after} в ${k}`)
  arr.splice(i + 1, 0, ...ps)
}
const addFigs = (k: string, f: Array<{ after: string; caption: string; src: string }>) => {
  const F = FIGS as unknown as Record<string, unknown[]>
  F[k] = [...(F[k] ?? []), ...f]
}
